SELECT store_id, repo_url, repo_branch, repo_username, repo_secret, auto_new, on_alert, scanned_until,
       repo_commit, repo_synced_at, repo_error, updated_at
FROM ai_store_config WHERE store_id = #{storeId}

mapper.update:
UPDATE ai_store_config
SET repo_url = #{value.repoUrl}, repo_branch = #{value.repoBranch}, repo_username = #{value.repoUsername},
    repo_secret = #{value.repoSecret}, auto_new = #{value.autoNew}, on_alert = #{value.onAlert},
    scanned_until = #{value.scannedUntil}, repo_commit = #{value.repoCommit},
    repo_synced_at = #{value.repoSyncedAt}, repo_error = #{value.repoError}, updated_at = #{value.updatedAt}
WHERE store_id = #{value.storeId}

mapper.select:
SELECT id, store_id, fingerprint, error_type, location, sample, host, occurrences, first_seen, last_seen,
       status, diagnosis_id
FROM error_group WHERE store_id = #{storeId} AND fingerprint = #{fingerprint}

SELECT id, store_id, fingerprint, error_type, location, sample, host, occurrences, first_seen, last_seen,
       status, diagnosis_id
FROM error_group WHERE id = #{id}

SELECT id, store_id, fingerprint, error_type, location, sample, host, occurrences, first_seen, last_seen,
       status, diagnosis_id
FROM error_group

    store_id = #{storeId}
    AND status = #{status}

ORDER BY last_seen DESC, id DESC
LIMIT #{limit}

SELECT 
FROM ai_diagnosis
WHERE created_at >= #{since}
AND store_id = #{storeId}
AND review_state = #{reviewState}
AND trigger_type = #{triggerType}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

